package au.monster.tracker;

import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import java.io.ByteArrayOutputStream;
import java.util.*;

/** Version-2 document domain; all operations share the legacy Store's transaction lock. */
public final class BusinessStore {
    private final Store store;
    public BusinessStore(Store store){this.store=store;}
    public record View(List<Purchases.Document> documents,Map<String,Long> received,Set<String> cancelled,long expenses){}
    private SQLiteDatabase db(){return store.database();}
    private static void body(SQLiteDatabase db,String table,String id,Map<String,Object> value,ContentValues extra){extra.put("id",id);extra.put("body",Json.write(value));db.insertOrThrow(table,null,extra);}
    private static List<Map<String,Object>> bodies(SQLiteDatabase db,String table){List<Map<String,Object>> out=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT body FROM "+table+" ORDER BY rowid",null)){while(c.moveToNext())out.add(Purchases.map(Json.parse(c.getString(0))));}return out;}
    private static String existing(SQLiteDatabase db,String table,String id){try(Cursor c=db.rawQuery("SELECT body FROM "+table+" WHERE id=?",new String[]{id})){return c.moveToFirst()?c.getString(0):null;}}
    private static void audit(SQLiteDatabase db,String id,String action,String entity,Long date,long recorded,Map<String,Object> payload){ContentValues v=new ContentValues();v.put("id",id);v.put("recorded_at",recorded);if(date==null)v.putNull("occurred_at");else v.put("occurred_at",date);v.put("action",action);v.put("entity_id",entity);v.put("payload",Json.write(payload));db.insertOrThrow("audit",null,v);}
    private static void receipt(SQLiteDatabase db,Purchases.Receipt r){try(Cursor c=db.rawQuery("SELECT mime,length(content) FROM supplier_receipts WHERE hash=?",new String[]{r.hash()})){if(c.moveToFirst()){if(!c.getString(0).equals(r.mime())||c.getLong(1)!=r.content().length)Purchases.bad("Conflicting receipt content.");return;}}ContentValues v=new ContentValues();v.put("hash",r.hash());v.put("mime",r.mime());v.put("content",r.content());db.insertOrThrow("supplier_receipts",null,v);}
    public void add(Purchases.Document doc,Purchases.Receipt attachment){synchronized(store){SQLiteDatabase db=db();db.beginTransaction();try{String serialized=Json.write(Purchases.documentMap(doc)),old=existing(db,"documents",doc.id());if(old!=null){if(!old.equals(serialized))Purchases.bad("Conflicting document ID.");db.setTransactionSuccessful();return;}
        if(attachment!=null){if(!attachment.hash().equals(doc.receiptHash()))Purchases.bad("Receipt link mismatch.");receipt(db,attachment);}else if(doc.receiptHash()!=null)Purchases.bad("Attach the original receipt before saving.");
        if(doc.receiptHash()!=null)try(Cursor legacy=db.rawQuery("SELECT event_id FROM receipts WHERE sha256=?",new String[]{doc.receiptHash()})){if(legacy.moveToFirst())Purchases.bad("This receipt is already attached to transaction "+legacy.getString(0)+". Do not record the same purchase twice.");}
        if(doc.receiptHash()!=null)try(Cursor c=db.rawQuery("SELECT id FROM documents WHERE receipt_hash=?",new String[]{doc.receiptHash()})){if(c.moveToFirst())Purchases.bad("This original receipt is already recorded ("+c.getString(0)+"). No duplicate purchase saved.");}
        if(doc.invoiceKey()!=null)try(Cursor c=db.rawQuery("SELECT id FROM documents WHERE invoice_key=?",new String[]{doc.invoiceKey()})){if(c.moveToFirst())Purchases.bad("Supplier/reference already exists. Check the saved purchase before adding another.");}
        ContentValues v=new ContentValues();v.put("kind",doc.kind());if(doc.receiptHash()==null)v.putNull("receipt_hash");else v.put("receipt_hash",doc.receiptHash());if(doc.invoiceKey()==null)v.putNull("invoice_key");else v.put("invoice_key",doc.invoiceKey());body(db,"documents",doc.id(),Purchases.documentMap(doc),v);
        for(var line:doc.lines()){ContentValues l=new ContentValues();l.put("document_id",doc.id());body(db,"purchase_lines",line.id(),Purchases.lineMap(line),l);}
        audit(db,"document-"+doc.id(),"document."+doc.kind(),doc.id(),doc.date(),doc.recordedAt(),Purchases.documentMap(doc));db.setTransactionSuccessful();
    }finally{db.endTransaction();}}}
    public View view(){synchronized(store){SQLiteDatabase db=db();List<Purchases.Document> docs=new ArrayList<>();for(var m:bodies(db,"documents"))docs.add(Purchases.document(m));Set<String> cancelled=new HashSet<>();for(var m:bodies(db,"document_cancellations"))cancelled.add(Purchases.str(m,"documentId"));Map<String,Long> received=received(db);long expenses=0;for(var d:docs)if(!cancelled.contains(d.id())){if(d.kind().equals("expense"))expenses+=d.amount();else for(var l:d.lines())if(!l.stock())expenses+=l.cost();}return new View(Ledger.copy(docs),Collections.unmodifiableMap(received),Collections.unmodifiableSet(cancelled),expenses);}}
    private static Map<String,Long> received(SQLiteDatabase db){Map<String,Long> result=new HashMap<>();try(Cursor c=db.rawQuery("SELECT d.line_id,e.quantity FROM deliveries d JOIN events e ON e.id=d.event_id WHERE NOT EXISTS(SELECT 1 FROM events u WHERE u.type='undo' AND u.target=e.id) ORDER BY d.rowid",null)){while(c.moveToNext())result.put(c.getString(0),result.getOrDefault(c.getString(0),0L)+c.getLong(1));}return result;}
    public void receive(String commandId,String lineId,long quantity,long date,String note){synchronized(store){Purchases.checkId(commandId);SQLiteDatabase db=db();db.beginTransaction();try{String old=existing(db,"deliveries",commandId);if(old!=null){Map<String,Object> m=Purchases.map(Json.parse(old));if(!Purchases.str(m,"lineId").equals(lineId)||Purchases.num(m,"quantity")!=quantity||Purchases.num(m,"timestamp")!=date||!Purchases.str(m,"note").equals(note))Purchases.bad("Conflicting delivery ID.");db.setTransactionSuccessful();return;}
        Purchases.Line line;String document;try(Cursor c=db.rawQuery("SELECT body,document_id FROM purchase_lines WHERE id=?",new String[]{lineId})){if(!c.moveToFirst())throw new IllegalArgumentException("Purchase line not found.");line=Purchases.line(Json.parse(c.getString(0)));document=c.getString(1);}
        try(Cursor c=db.rawQuery("SELECT 1 FROM document_cancellations WHERE document_id=?",new String[]{document})){if(c.moveToFirst())Purchases.bad("This purchase was cancelled. No goods may be received against it.");}
        long before=received(db).getOrDefault(lineId,0L),allocated=0;try(Cursor c=db.rawQuery("SELECT COALESCE(SUM(e.cost),0) FROM deliveries d JOIN events e ON e.id=d.event_id WHERE d.line_id=? AND NOT EXISTS(SELECT 1 FROM events u WHERE u.type='undo' AND u.target=e.id)",new String[]{lineId})){if(c.moveToFirst())allocated=c.getLong(0);}long cost=Purchases.remainingCost(line,before,allocated,quantity);long recorded=System.currentTimeMillis();String eventId="received-"+commandId;
        var event=new Ledger.Event(eventId,date,recorded,"restock",quantity,"none",0,0,cost,"Supplier delivery: "+line.product()+" · "+note,null);store.record(event);
        Map<String,Object> m=new LinkedHashMap<>();m.put("id",commandId);m.put("lineId",lineId);m.put("eventId",eventId);m.put("quantity",quantity);m.put("cost",cost);m.put("timestamp",date);m.put("recordedAt",recorded);m.put("note",note);ContentValues v=new ContentValues();v.put("line_id",lineId);v.put("event_id",eventId);body(db,"deliveries",commandId,m,v);audit(db,"delivery-"+commandId,"purchase.received",document,date,recorded,m);db.setTransactionSuccessful();
    }finally{db.endTransaction();}}}
    public void cancel(String id,String documentId,String note){synchronized(store){Purchases.checkId(id);if(note.trim().isEmpty()||note.length()>500)Purchases.bad("Give a correction reason (up to 500 characters).");SQLiteDatabase db=db();db.beginTransaction();try{String existing=existing(db,"document_cancellations",id);if(existing!=null){var previous=Purchases.map(Json.parse(existing));if(!Purchases.str(previous,"documentId").equals(documentId)||!Purchases.str(previous,"note").equals(note))Purchases.bad("Conflicting cancellation ID.");db.setTransactionSuccessful();return;}if(existing(db,"documents",documentId)==null)Purchases.bad("Document not found.");long now=System.currentTimeMillis();Map<String,Object> m=new LinkedHashMap<>();m.put("id",id);m.put("documentId",documentId);m.put("note",note);m.put("recordedAt",now);ContentValues v=new ContentValues();v.put("document_id",documentId);body(db,"document_cancellations",id,m,v);audit(db,"cancel-"+id,"document.cancelled",documentId,now,now,m);db.setTransactionSuccessful();}finally{db.endTransaction();}}}
    public String receiptMime(String hash){synchronized(store){try(Cursor c=db().rawQuery("SELECT mime FROM supplier_receipts WHERE hash=?",new String[]{hash})){if(!c.moveToFirst())throw new IllegalArgumentException("Original receipt not found.");return c.getString(0);}}}
    public Purchases.Receipt original(String hash){synchronized(store){SQLiteDatabase db=db();String mime=receiptMime(hash);ByteArrayOutputStream bytes=new ByteArrayOutputStream();int offset=1;while(true){try(Cursor c=db.rawQuery("SELECT substr(content,?,262144) FROM supplier_receipts WHERE hash=?",new String[]{String.valueOf(offset),hash})){if(!c.moveToFirst())Purchases.bad("Receipt is missing.");byte[] chunk=c.getBlob(0);if(chunk.length==0)break;bytes.write(chunk,0,chunk.length);offset+=chunk.length;if(bytes.size()>Purchases.MAX_RECEIPT)Purchases.bad("Receipt exceeds size limit.");}}return new Purchases.Receipt(hash,mime,bytes.toByteArray());}}
    public List<Map<String,Object>> audit(){synchronized(store){List<Map<String,Object>> out=new ArrayList<>();try(Cursor c=db().rawQuery("SELECT id,recorded_at,occurred_at,action,entity_id,payload,event_id FROM audit ORDER BY seq",null)){while(c.moveToNext()){Map<String,Object> m=new LinkedHashMap<>();m.put("id",c.getString(0));m.put("recordedAt",c.getLong(1));m.put("date",c.isNull(2)?null:c.getLong(2));m.put("action",c.getString(3));m.put("entityId",c.getString(4));m.put("payload",Purchases.map(Json.parse(c.getString(5))));m.put("eventId",c.isNull(6)?null:c.getString(6));out.add(m);}}return out;}}
    public Map<String,Object> export(){synchronized(store){SQLiteDatabase db=db();Map<String,Object> all=new LinkedHashMap<>();all.put("documents",bodies(db,"documents"));all.put("deliveries",bodies(db,"deliveries"));all.put("cancellations",bodies(db,"document_cancellations"));all.put("audit",audit());List<Object> receipts=new ArrayList<>();List<String> hashes=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT hash FROM supplier_receipts ORDER BY hash",null)){while(c.moveToNext())hashes.add(c.getString(0));}for(String hash:hashes){var r=original(hash);Map<String,Object> m=new LinkedHashMap<>();m.put("hash",hash);m.put("mime",r.mime());m.put("content",Base64.getEncoder().encodeToString(r.content()));receipts.add(m);}all.put("receipts",receipts);return all;}}
    /** Called inside Store's existing import transaction; all rows merge or all roll back. */
    void restore(Map<String,Object> all,List<Ledger.Event> merged){if(all==null)return;BusinessBackup.validate(all,merged);SQLiteDatabase db=db();for(Object value:Purchases.list(all.get("receipts"))){var m=Purchases.map(value);receipt(db,new Purchases.Receipt(Purchases.str(m,"hash"),Purchases.str(m,"mime"),Base64.getDecoder().decode(Purchases.str(m,"content"))));}
        for(Object value:Purchases.list(all.get("documents"))){var doc=Purchases.document(value);String current=existing(db,"documents",doc.id());if(current!=null){if(!current.equals(Json.write(Purchases.documentMap(doc))))Purchases.bad("Conflicting purchase/expense: "+doc.id());continue;}ContentValues v=new ContentValues();v.put("kind",doc.kind());v.put("receipt_hash",doc.receiptHash());v.put("invoice_key",doc.invoiceKey());body(db,"documents",doc.id(),Purchases.documentMap(doc),v);for(var l:doc.lines()){ContentValues x=new ContentValues();x.put("document_id",doc.id());body(db,"purchase_lines",l.id(),Purchases.lineMap(l),x);}}
        for(String table:Ledger.list("deliveries","document_cancellations")){String key=table.equals("deliveries")?"deliveries":"cancellations";for(Object value:Purchases.list(all.get(key))){var m=Purchases.map(value);String id=Purchases.str(m,"id"),current=existing(db,table,id);if(current!=null){if(!current.equals(Json.write(m)))Purchases.bad("Conflicting delivery/correction.");continue;}ContentValues v=new ContentValues();if(table.equals("deliveries")){v.put("line_id",Purchases.str(m,"lineId"));v.put("event_id",Purchases.str(m,"eventId"));}else v.put("document_id",Purchases.str(m,"documentId"));body(db,table,id,m,v);}}
        for(Object value:Purchases.list(all.get("audit"))){var m=Purchases.map(value);String id=Purchases.str(m,"id");try(Cursor c=db.rawQuery("SELECT payload,entity_id,action FROM audit WHERE id=?",new String[]{id})){if(c.moveToFirst()){if(!c.getString(0).equals(Json.write(m.get("payload")))||!c.getString(1).equals(Purchases.str(m,"entityId"))||!c.getString(2).equals(Purchases.str(m,"action")))Purchases.bad("Conflicting audit record.");continue;}}if(m.get("eventId")!=null)Purchases.bad("Ledger audit reference is missing from restored events.");audit(db,id,Purchases.str(m,"action"),Purchases.str(m,"entityId"),m.get("date")==null?null:Purchases.num(m,"date"),Purchases.num(m,"recordedAt"),Purchases.map(m.get("payload")));}
    }
}
